/* Opt-in WLKR gallery typography. Load the application's licensed Geist font first. */
.wlkr-typography {
  font-family: var(--font-sans, var(--font-geist-sans, Geist, Arial, Helvetica, sans-serif));
  --paper: var(--background, #fff);
  --ink: var(--foreground, #010101);
  --line: var(--border, #dedede);
}
.wlkr-layout { max-width:1512px; margin-inline:auto; padding-inline:6.2%; }
.wlkr-display { font-family:var(--font-sans, var(--font-geist-sans, Geist, Arial, Helvetica, sans-serif)); font-size:clamp(64px,8.3vw,124px); line-height:.96; font-weight:620; letter-spacing:-.078em; }
.wlkr-intro-copy { max-width:34rem; font-size:16px; line-height:1.6; color:var(--muted-foreground,#696969); }
.wlkr-reading { max-width:70ch; font-size:14px; line-height:1.75; }
.wlkr-caption { font-size:12px; line-height:1.65; color:var(--muted-foreground,#696969); }
.wlkr-stack { display:flex; flex-direction:column; gap:24px; }
@media(max-width:900px){.wlkr-layout{padding-inline:6%}.wlkr-intro-copy{font-size:15px}}
@media(max-width:620px){.wlkr-display{font-size:68px}.wlkr-intro-copy{max-width:300px}}
